Title:
"Maria Torres"

Text:
"She founded Lumen Works."

OUTPUT:

{
  "statements": [
    {
      "subject": {
        "value": "Maria Torres",
        "evidence": [
          {
            "segment": "title",
            "quote": "Maria Torres",
            "occurrence": 1
          },
          {
            "segment": "text",
